100	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
101	// and verbose [info] log (VsimFilter), relaying only the program's own output
102	// and any real diagnostics, then restate the lifted cycle count as andesim's own
103	// one-line result under the [andesim] prefix. The count is printed AFTER the run
104	// (the engine logs it at exit), so it follows the program output. Returns the
105	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
106	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
107	int run_cycle_clean(const std::vector<std::string>& argv) {
108	  VsimFilter filter;
109	  const int rc = run_line_filtered(
110	      argv, [&filter](int stream, std::string_view line) {
111	        std::FILE* dst = nullptr;
112	        switch (filter.classify(stream, line)) {
113	          case VsimFilter::Dest::kStdout: dst = stdout; break;
114	          case VsimFilter::Dest::kStderr: dst = stderr; break;
115	          case VsimFilter::Dest::kDrop: return;
116	        }
117	        std::fwrite(line.data(), 1, line.size(), dst);
118	        std::fputc('\n', dst);
119	      });
120	  if (const std::optional<uint64_t> c = filter.cycles())
121	    log_result(kLogInfo, "[andesim] %llu cycles",
122	               static_cast<unsigned long long>(*c));
123	  return rc;
124	}
