126	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
127	// then run the resolved engine standalone with `extra` (model flags the
128	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
129	// `clean_output` picks how the engine's output is presented: fast inherits the
130	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
131	// semihosting console works unchanged); cycle filters out the engine's banner +
132	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
133	// exit code propagates. The per-model engine + selection are resolved by the
134	// caller; `model` here only labels the positional diagnostics.
135	// `boot_elf_override`: --runtime linux (U2) boots a staged vlinux.elf instead
136	// of the positional ELF (which stays the APP path -- still validated to
137	// exist, still what the manifest embeds); empty means "boot the ELF as given"
138	// (every other caller).
139	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
140	                   const char* model, const std::vector<std::string>& extra = {},
141	                   bool clean_output = false,
142	                   const std::string& boot_elf_override = {}) {
143	  if (int rc = check_one_elf(cli, model)) return rc;
144	  // QEMU's -bios flag searches its data directory for relative paths rather
145	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
146	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
147	  if (elf.empty()) return 2;
148	  const std::string& boot_elf =
149	      boot_elf_override.empty() ? elf : boot_elf_override;
150	  std::vector<std::string> args = extra;
151	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
152	  std::string err;
153	  const std::vector<std::string> argv =
154	      passthrough_argv(eng, "standalone", boot_elf, args, err);
155	  if (!err.empty()) {
156	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
157	    return 2;
158	  }
159	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
160	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
161	  if (cli.dry_run)
162	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
163	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
164	  // wedged engine still leaves the exact command in the log.
165	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
166	           render_argv(argv).c_str());
167	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
168	}
